    .arg(&script_path)
    .output()
    .expect("Failed to execute strykelang binary");
if !output.status.success() {
    panic!("strykelang execution failed: {}", String::from_utf8_lossy(&output.stderr));
}
let mut out_file = File::create(&output_path).expect("Cannot create output file");
out_file.write_all(&output.stdout).expect("Failed to write output");
